{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C73"],
      "claim": "Zalcitabine, a closely related nucleoside analog, showed absolute oral bioavailability of 86–100% in adults, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Lamivudine, another nucleoside reverse transcriptase inhibitor, had absolute oral bioavailability of 87% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Emtricitabine, a fluorinated nucleoside analog, had absolute oral bioavailability of 93% in humans; the query also contains a fluorine on the nucleobase, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Cladribine, a purine nucleoside analog, showed oral bioavailability of 48%, still above the 20% threshold, supporting high F despite being lower than pyrimidine analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "Didanosine/ddA, a purine dideoxynucleoside, showed low F around 0.22 under fasting conditions, but this reflects acid lability and the dideoxy structure not shared by the full ribose query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a polar 2-amino-6-fluoropurine ribonucleoside. The closest high-transfer nucleoside analogs—zalcitabine, lamivudine, and emtricitabine—show high oral bioavailability (87–100%). The only low-F evidence comes from acid-labile dideoxypurine nucleosides, a liability absent in the full ribose query. Therefore F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for 2-amino-6-fluoropurine riboside itself.",
    "Potential acid lability or first-pass metabolism specific to the 6-fluoro purine riboside was not directly tested.",
    "Most analog data come from patient populations or specific formulations, not identical conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

